from pdfminer.high_level import extract_text
from pptx import Presentation
import docx


def extract(path: Path, limit_chars=12000):
    suf = path.suffix.lower()
    try:
        if suf == '.pdf':
            # first two pages only
            txt = extract_text(str(path), page_numbers=[0,1])
            return (txt or '')[:limit_chars]
        if suf == '.docx':
            d = docx.Document(str(path))
            txt = '\n'.join(p.text for p in d.paragraphs)
            return (txt or '')[:limit_chars]
        if suf == '.pptx':
            pres = Presentation(str(path))
            chunks = []
            for slide in pres.slides:
                for shape in slide.shapes:
                    if hasattr(shape, 'text'):
                        t = shape.text.strip()
                        if t:
                            chunks.append(t)
                if sum(len(c) for c in chunks) > limit_chars:
                    break
            return ('\n'.join(chunks))[:limit_chars]
    except Exception as e:
        return ''
    return ''


def score(text: str):
    t = text.lower()
    scores = {}
    for cat, regs in KW_RE.items():
        s = 0
        for r in regs:
            m = r.findall(t)
            if m:
                s += min(len(m), 5)  # cap each keyword influence
        scores[cat] = s
    return scores

